window.RA_DATA={"own": {"rs_src": "// Prints the real addresses behind the ownership animation: a Vec is three\n// machine words on the stack (pointer, capacity, length) and a buffer on the heap.\nfn show(step: &str, name: &str, v: &Vec<u32>) {\n    println!(\n        \"{step} {name} stack={:p} heap={:p} len={} cap={} data={:?}\",\n        v as *const Vec<u32>, v.as_ptr(), v.len(), v.capacity(), v\n    );\n}\n\nfn main() {\n    println!(\"size_of::<Vec<u32>>() = {}\", std::mem::size_of::<Vec<u32>>());\n    let mut v: Vec<u32> = Vec::with_capacity(3);\n    v.extend([10, 20, 30]);\n    show(\"1\", \"v\", &v);\n    let r = &v; // a shared borrow: a pointer to v's stack slot\n    println!(\"2 r points to {:p} (v's stack slot), r.len()={}\", r as *const Vec<u32>, r.len());\n    v.push(40); // r is no longer used, so v may be mutated: the buffer is full, so it grows\n    show(\"3\", \"v\", &v);\n    let m = &mut v; // one exclusive borrow\n    m[0] = 11;\n    println!(\"4 m points to {:p}, wrote m[0]=11\", m as *const Vec<u32>);\n    let w = v; // move: the three words are copied to w's slot, the heap buffer is not touched\n    show(\"5\", \"w\", &w);\n    let c = w.clone(); // clone: a new heap buffer with a copy of the elements\n    show(\"6\", \"c\", &c);\n    drop(w); // w's buffer is freed now\n    println!(\"7 dropped w\");\n    show(\"8\", \"c\", &c);\n}", "py_src": "# The same steps in Python: names point at objects; nothing is moved.\nimport sys\nv = [10, 20, 30]\nprint(\"1 v id=%#x refcount=%d len=%d\" % (id(v), sys.getrefcount(v) - 1, len(v)))\nr = v\nprint(\"2 r id=%#x (same object) refcount=%d\" % (id(r), sys.getrefcount(v) - 1))\nv.append(40)\nprint(\"3 v id=%#x r sees %s\" % (id(v), r))\nm = v\nm[0] = 11\nprint(\"4 m id=%#x refcount=%d v=%s\" % (id(m), sys.getrefcount(v) - 1, v))\nw = v\nprint(\"5 w id=%#x refcount=%d (v still usable: %s)\" % (id(w), sys.getrefcount(v) - 1, v))\nc = w.copy()\nprint(\"6 c id=%#x (new object) refcount=%d\" % (id(c), sys.getrefcount(c) - 1))\ndel w\nprint(\"7 del w: object still alive, refcount=%d (v, r, m remain)\" % (sys.getrefcount(v) - 1))\nprint(\"8 c=%s v=%s\" % (c, v))", "rs_log": "$ rustc --edition 2024 own_anim.rs && ./own_anim\nsize_of::<Vec<u32>>() = 24\n1 v stack=0x16da0a2a8 heap=0x102d3d4a0 len=3 cap=3 data=[10, 20, 30]\n2 r points to 0x16da0a2a8 (v's stack slot), r.len()=3\n3 v stack=0x16da0a2a8 heap=0x102d3d510 len=4 cap=6 data=[10, 20, 30, 40]\n4 m points to 0x16da0a2a8, wrote m[0]=11\n5 w stack=0x16da0a350 heap=0x102d3d510 len=4 cap=6 data=[11, 20, 30, 40]\n6 c stack=0x16da0a368 heap=0x102d3d4a0 len=4 cap=4 data=[11, 20, 30, 40]\n7 dropped w\n8 c stack=0x16da0a368 heap=0x102d3d4a0 len=4 cap=4 data=[11, 20, 30, 40]\n", "py_log": "$ python3.14 own_anim.py\n1 v id=0x105e26140 refcount=1 len=3\n2 r id=0x105e26140 (same object) refcount=2\n3 v id=0x105e26140 r sees [10, 20, 30, 40]\n4 m id=0x105e26140 refcount=3 v=[11, 20, 30, 40]\n5 w id=0x105e26140 refcount=4 (v still usable: [11, 20, 30, 40])\n6 c id=0x10a8842c0 (new object) refcount=1\n7 del w: object still alive, refcount=3 (v, r, m remain)\n8 c=[11, 20, 30, 40] v=[11, 20, 30, 40]\n"}, "gate": {"err": {"src": "fn main() {\n    let mut v = vec![1];\n    let first = &v[0];\n    v.push(2);\n    println!(\"{first}\");\n}", "out": "$ rustc --edition 2024 gate_err.rs\nerror[E0502]: cannot borrow `v` as mutable because it is also borrowed as immutable\n --> gate_err.rs:4:5\n  |\n3 |     let first = &v[0];\n  |                  - immutable borrow occurs here\n4 |     v.push(2);\n  |     ^^^^^^^^^ mutable borrow occurs here\n5 |     println!(\"{first}\");\n  |                ----- immutable borrow later used here\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0502`.\n[exit code 1]\n"}, "fix": {"src": "fn main() {\n    let mut v = vec![1];\n    let first = v[0]; // copy the i32 out instead of borrowing it\n    v.push(2);\n    println!(\"{first} {:?}\", v);\n}", "out": "$ rustc --edition 2024 gate_fix.rs && ./gate_fix\n1 [1, 2]\n"}, "reorder": {"src": "fn main() {\n    let mut v = vec![1];\n    let first = &v[0];\n    println!(\"{first}\"); // last use of the borrow\n    v.push(2); // fine: the shared borrow has already ended\n    println!(\"{:?}\", v);\n}", "out": "$ rustc --edition 2024 gate_reorder.rs && ./gate_reorder\n1\n[1, 2]\n"}}, "bc": [{"id": "01_use_after_move", "group": "Moves", "title": "Use after move", "code": "E0382", "kind": "compile", "py": "In Python <code>count(prompt)<\/code> passes a reference to the same string; <code>prompt<\/code> stays usable.", "read": "Three labels tell the story in order: where the value was created (and why it moves: <code>String<\/code> is not <code>Copy<\/code>), where it moved (<i>value moved here<\/i>), and the later use (<i>value borrowed here after move<\/i>). The note points at the cause: the parameter type <code>String<\/code> takes ownership.", "why": "The function only reads the text, so it should borrow: <code>&amp;str<\/code> accepts a <code>&amp;String<\/code> and a literal alike. The compiler's other suggestion, <code>.clone()<\/code>, also compiles but copies the whole buffer: use it when the callee really needs its own copy.", "err_src": "fn count(s: String) -> usize {\n    s.split_whitespace().count()\n}\n\nfn main() {\n    let prompt = String::from(\"explain the borrow checker\");\n    let n = count(prompt);\n    println!(\"{n} words in {prompt}\");\n}", "err_out": "$ rustc --edition 2024 01_use_after_move_err.rs\nerror[E0382]: borrow of moved value: `prompt`\n --> 01_use_after_move_err.rs:8:29\n  |\n6 |     let prompt = String::from(\"explain the borrow checker\");\n  |         ------ move occurs because `prompt` has type `String`, which does not implement the `Copy` trait\n7 |     let n = count(prompt);\n  |                   ------ value moved here\n8 |     println!(\"{n} words in {prompt}\");\n  |                             ^^^^^^ value borrowed here after move\n  |\nnote: consider changing this parameter type in function `count` to borrow instead if owning the value isn't necessary\n --> 01_use_after_move_err.rs:1:13\n  |\n1 | fn count(s: String) -> usize {\n  |    -----    ^^^^^^ this parameter takes ownership of the value\n  |    |\n  |    in this function\nhelp: consider cloning the value if the performance cost is acceptable\n  |\n7 |     let n = count(prompt.clone());\n  |                         ++++++++\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0382`.\n[exit code 1]\n", "fix_src": "fn count(s: &str) -> usize {\n    s.split_whitespace().count()\n}\n\nfn main() {\n    let prompt = String::from(\"explain the borrow checker\");\n    let n = count(&prompt); // lend it instead of giving it away\n    println!(\"{n} words in {prompt}\");\n}", "fix_out": "$ rustc --edition 2024 01_use_after_move_fix.rs && ./01_use_after_move_fix\n4 words in explain the borrow checker\n"}, {"id": "02_loop_move", "group": "Moves", "title": "Move inside a loop", "code": "E0382", "kind": "compile", "py": "A Python list would hold three references to one string object.", "read": "<i>value moved here, in previous iteration of loop<\/i>: the first iteration moved <code>tag<\/code> into the vector, so the second has nothing left to move. The <i>inside of this loop<\/i> label marks the loop that repeats the move.", "why": "Each tuple must own a <code>String<\/code>, so each needs its own copy: <code>tag.clone()<\/code> per iteration (three small allocations). If the copies are wasteful, store <code>&amp;str<\/code> borrowed from <code>tag<\/code>, or share one <code>Rc&lt;str&gt;<\/code>.", "err_src": "fn main() {\n    let tag = String::from(\"batch\");\n    let mut out = Vec::new();\n    for i in 0..3 {\n        out.push((i, tag));\n    }\n    println!(\"{out:?}\");\n}", "err_out": "$ rustc --edition 2024 02_loop_move_err.rs\nerror[E0382]: use of moved value: `tag`\n --> 02_loop_move_err.rs:5:22\n  |\n2 |     let tag = String::from(\"batch\");\n  |         --- move occurs because `tag` has type `String`, which does not implement the `Copy` trait\n3 |     let mut out = Vec::new();\n4 |     for i in 0..3 {\n  |     ------------- inside of this loop\n5 |         out.push((i, tag));\n  |                      ^^^ value moved here, in previous iteration of loop\n  |\nhelp: consider cloning the value if the performance cost is acceptable\n  |\n5 |         out.push((i, tag.clone()));\n  |                         ++++++++\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0382`.\n[exit code 1]\n", "fix_src": "fn main() {\n    let tag = String::from(\"batch\");\n    let mut out = Vec::new();\n    for i in 0..3 {\n        out.push((i, tag.clone())); // each element needs its own String\n    }\n    println!(\"{out:?}\");\n}", "fix_out": "$ rustc --edition 2024 02_loop_move_fix.rs && ./02_loop_move_fix\n[(0, \"batch\"), (1, \"batch\"), (2, \"batch\")]\n"}, {"id": "10_move_out_of_index", "group": "Moves", "title": "Move out of a Vec by indexing", "code": "E0507", "kind": "compile", "py": "<code>first = names[0]<\/code> in Python is just a second reference.", "read": "<i>cannot move out of index<\/i>: taking the <code>String<\/code> would leave a hole in the vector. The two help blocks list the fixes in order of cost.", "why": "Borrow (<code>&amp;names[0]<\/code>, free), clone (a copy), or remove it from the vector (<code>remove<\/code>, <code>swap_remove<\/code>, <code>pop<\/code>, or <code>std::mem::take<\/code>) so the vector no longer owns it.", "err_src": "fn main() {\n    let names = vec![String::from(\"ada\"), String::from(\"bob\")];\n    let first = names[0];\n    println!(\"{first} {}\", names.len());\n}", "err_out": "$ rustc --edition 2024 10_move_out_of_index_err.rs\nerror[E0507]: cannot move out of index of `Vec<String>`\n --> 10_move_out_of_index_err.rs:3:17\n  |\n3 |     let first = names[0];\n  |                 ^^^^^^^^ move occurs because value has type `String`, which does not implement the `Copy` trait\n  |\nhelp: consider borrowing here\n  |\n3 |     let first = &names[0];\n  |                 +\nhelp: consider cloning the value if the performance cost is acceptable\n  |\n3 |     let first = names[0].clone();\n  |                         ++++++++\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0507`.\n[exit code 1]\n", "fix_src": "fn main() {\n    let names = vec![String::from(\"ada\"), String::from(\"bob\")];\n    let first = &names[0]; // borrow it\n    let copy = names[1].clone(); // or clone it\n    println!(\"{first} {copy} {}\", names.len());\n    let mut names = names;\n    let taken = names.remove(0); // or take it out of the Vec for good\n    println!(\"took {taken}, left {names:?}\");\n}", "fix_out": "$ rustc --edition 2024 10_move_out_of_index_fix.rs && ./10_move_out_of_index_fix\nada bob 2\ntook ada, left [\"bob\"]\n"}, {"id": "03_push_while_borrowed", "group": "Borrows", "title": "Push while a reference is alive", "code": "E0502", "kind": "compile", "py": "Python lists also reallocate when they grow, but a Python reference points at the element object, never into the list's buffer, so nothing dangles.", "read": "The classic three-label shape: <i>immutable borrow occurs here<\/i> (the start of <code>best<\/code>), <i>mutable borrow occurs here<\/i> (<code>push<\/code> needs <code>&amp;mut<\/code>), <i>immutable borrow later used here<\/i> (the reason the first borrow is still alive). Remove any one of the three and it compiles.", "why": "<code>push<\/code> may move the buffer to a bigger block (the hero at the top of the page, step 3), which would leave <code>best<\/code> pointing at freed memory. Copying the <code>f64<\/code> out ends the borrow at once. Moving the <code>println!<\/code> above the <code>push<\/code> would also work.", "err_src": "fn main() {\n    let mut scores = vec![0.9, 0.4];\n    let best = &scores[0];\n    scores.push(0.7);\n    println!(\"best {best}\");\n}", "err_out": "$ rustc --edition 2024 03_push_while_borrowed_err.rs\nerror[E0502]: cannot borrow `scores` as mutable because it is also borrowed as immutable\n --> 03_push_while_borrowed_err.rs:4:5\n  |\n3 |     let best = &scores[0];\n  |                 ------ immutable borrow occurs here\n4 |     scores.push(0.7);\n  |     ^^^^^^^^^^^^^^^^ mutable borrow occurs here\n5 |     println!(\"best {best}\");\n  |                     ---- immutable borrow later used here\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0502`.\n[exit code 1]\n", "fix_src": "fn main() {\n    let mut scores = vec![0.9, 0.4];\n    let best = scores[0]; // f64 is Copy: take the value, not a reference\n    scores.push(0.7);\n    println!(\"best {best} of {scores:?}\");\n}", "fix_out": "$ rustc --edition 2024 03_push_while_borrowed_fix.rs && ./03_push_while_borrowed_fix\nbest 0.9 of [0.9, 0.4, 0.7]\n"}, {"id": "04_two_mut", "group": "Borrows", "title": "Two &mut into one Vec", "code": "E0499", "kind": "compile", "py": "Python has no such rule: any number of names may change the same list.", "read": "<i>first mutable borrow<\/i>, <i>second mutable borrow<\/i>, <i>first borrow later used<\/i>. The help line names the standard tool: <code>split_at_mut<\/code>.", "why": "The checker does not track indexes, so <code>&amp;mut weights[0]<\/code> borrows all of <code>weights<\/code>. <code>swap(i, j)<\/code> takes one <code>&amp;mut<\/code>; <code>split_at_mut<\/code> returns two non-overlapping halves (it is written with <code>unsafe<\/code> inside, behind a safe signature).", "err_src": "fn main() {\n    let mut weights = vec![1.0, 2.0, 3.0];\n    let a = &mut weights[0];\n    let b = &mut weights[2];\n    std::mem::swap(a, b);\n    println!(\"{weights:?}\");\n}", "err_out": "$ rustc --edition 2024 04_two_mut_err.rs\nerror[E0499]: cannot borrow `weights` as mutable more than once at a time\n --> 04_two_mut_err.rs:4:18\n  |\n3 |     let a = &mut weights[0];\n  |                  ------- first mutable borrow occurs here\n4 |     let b = &mut weights[2];\n  |                  ^^^^^^^ second mutable borrow occurs here\n5 |     std::mem::swap(a, b);\n  |                    - first borrow later used here\n  |\n  = help: use `.split_at_mut(position)` to obtain two mutable non-overlapping sub-slices\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0499`.\n[exit code 1]\n", "fix_src": "fn main() {\n    let mut weights = vec![1.0, 2.0, 3.0];\n    weights.swap(0, 2); // the method takes one &mut and both indexes\n    let (left, right) = weights.split_at_mut(2); // or: two non-overlapping &mut halves\n    std::mem::swap(&mut left[1], &mut right[0]);\n    println!(\"{weights:?}\");\n}", "fix_out": "$ rustc --edition 2024 04_two_mut_fix.rs && ./04_two_mut_fix\n[3.0, 1.0, 2.0]\n"}, {"id": "05_mutate_while_iterating", "group": "Borrows", "title": "Mutate while iterating", "code": "E0502", "kind": "compile", "py": "Python allows it, and the loop then sees its own appends: the recorded run below appends 20 again and again until a guard stops it.", "extra": [["bc_05_py", "The same loop in Python (with a guard so it stops)"]], "read": "The <code>for<\/code> loop holds a shared borrow of <code>queue<\/code> for its whole body; <code>push<\/code> inside needs an exclusive one. The help line suggests the two usual fixes.", "why": "Read first, write after: collect the changes into a separate vector, then <code>extend<\/code>. Or loop over indexes (<code>for i in 0..queue.len()<\/code>) when you really want to visit new items.", "err_src": "fn main() {\n    let mut queue = vec![1, 2, 3];\n    for x in &queue {\n        if *x == 2 {\n            queue.push(20);\n        }\n    }\n    println!(\"{queue:?}\");\n}", "err_out": "$ rustc --edition 2024 05_mutate_while_iterating_err.rs\nerror[E0502]: cannot borrow `queue` as mutable because it is also borrowed as immutable\n --> 05_mutate_while_iterating_err.rs:5:13\n  |\n3 |       for x in &queue {\n  |       -        ------\n  |       |        |\n  |       |        immutable borrow occurs here\n  |  _____|        immutable borrow later used here\n  | |\n4 | |         if *x == 2 {\n5 | |             queue.push(20);\n  | |             ^^^^^^^^^^^^^^ mutable borrow occurs here\n6 | |         }\n7 | |     }\n  | |_____- this for loop borrows `queue` immutably, preventing mutation within its body\n  |\n  = help: consider using an index-based loop instead, or collecting modifications into a separate collection\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0502`.\n[exit code 1]\n", "fix_src": "fn main() {\n    let mut queue = vec![1, 2, 3];\n    let extra: Vec<i32> = queue.iter().filter(|&&x| x == 2).map(|_| 20).collect();\n    queue.extend(extra); // read first, then write\n    println!(\"{queue:?}\");\n}", "fix_out": "$ rustc --edition 2024 05_mutate_while_iterating_fix.rs && ./05_mutate_while_iterating_fix\n[1, 2, 3, 20]\n", "extras": [{"label": "The same loop in Python (with a guard so it stops)", "out": "$ python3.14 05_mutate_while_iterating.py\n[1, 2, 3, 20, 20, 20, 20, 20, 20]\n"}]}, {"id": "11_not_mut", "group": "Borrows", "title": "&mut of a variable not declared mut", "code": "E0596", "kind": "compile", "py": "Every Python list is mutable.", "read": "<i>cannot borrow as mutable<\/i>, and the help shows the one-word fix with <code>+++<\/code> under the inserted text.", "why": "Mutability is part of the binding: <code>let mut probs<\/code>. It costs nothing at run time; it documents which variables change.", "err_src": "fn normalise(v: &mut Vec<f32>) {\n    let s: f32 = v.iter().sum();\n    for x in v.iter_mut() {\n        *x /= s;\n    }\n}\n\nfn main() {\n    let probs = vec![1.0, 3.0];\n    normalise(&mut probs);\n    println!(\"{probs:?}\");\n}", "err_out": "$ rustc --edition 2024 11_not_mut_err.rs\nerror[E0596]: cannot borrow `probs` as mutable, as it is not declared as mutable\n  --> 11_not_mut_err.rs:10:15\n   |\n10 |     normalise(&mut probs);\n   |               ^^^^^^^^^^ cannot borrow as mutable\n   |\nhelp: consider changing this to be mutable\n   |\n 9 |     let mut probs = vec![1.0, 3.0];\n   |         +++\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0596`.\n[exit code 1]\n", "fix_src": "fn normalise(v: &mut Vec<f32>) {\n    let s: f32 = v.iter().sum();\n    for x in v.iter_mut() {\n        *x /= s;\n    }\n}\n\nfn main() {\n    let mut probs = vec![1.0, 3.0];\n    normalise(&mut probs);\n    println!(\"{probs:?}\");\n}", "fix_out": "$ rustc --edition 2024 11_not_mut_fix.rs && ./11_not_mut_fix\n[0.25, 0.75]\n"}, {"id": "13_map_get_insert", "group": "Borrows", "title": "Get, or insert and return (a false alarm)", "code": "E0502", "kind": "compile", "py": "The same function in Python is fine, and here it is fine in Rust too: this code is safe.", "extra": [["bc_13_polonius", "The same file accepted by the next-generation checker (nightly, -Zpolonius=next)"]], "read": "<i>returning this value requires that <code>*cache<\/code> is borrowed for <code>'1<\/code><\/i>: because one branch returns the borrow, today's checker keeps it alive for the whole function, including the path that does not return it.", "why": "This is a known limitation of the current borrow checker (the conditional-return case); the Polonius checker on nightly accepts the same file (recorded below). On stable, the entry API does the lookup once and returns a reference either way.", "err_src": "use std::collections::HashMap;\n\n// Return the cached value, or insert one and return that.\nfn get_or_insert(cache: &mut HashMap<u32, String>, k: u32) -> &String {\n    if let Some(v) = cache.get(&k) {\n        return v;\n    }\n    cache.insert(k, format!(\"value {k}\"));\n    cache.get(&k).unwrap()\n}\n\nfn main() {\n    let mut cache = HashMap::new();\n    println!(\"{}\", get_or_insert(&mut cache, 7));\n}", "err_out": "$ rustc --edition 2024 13_map_get_insert_err.rs\nerror[E0502]: cannot borrow `*cache` as mutable because it is also borrowed as immutable\n --> 13_map_get_insert_err.rs:8:5\n  |\n4 | fn get_or_insert(cache: &mut HashMap<u32, String>, k: u32) -> &String {\n  |                         - let's call the lifetime of this reference `'1`\n5 |     if let Some(v) = cache.get(&k) {\n  |                      ----- immutable borrow occurs here\n6 |         return v;\n  |                - returning this value requires that `*cache` is borrowed for `'1`\n7 |     }\n8 |     cache.insert(k, format!(\"value {k}\"));\n  |     ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ mutable borrow occurs here\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0502`.\n[exit code 1]\n", "fix_src": "use std::collections::HashMap;\n\n// The entry API looks the key up once and hands back a reference either way.\nfn get_or_insert(cache: &mut HashMap<u32, String>, k: u32) -> &String {\n    cache.entry(k).or_insert_with(|| format!(\"value {k}\"))\n}\n\nfn main() {\n    let mut cache = HashMap::new();\n    println!(\"{}\", get_or_insert(&mut cache, 7));\n    println!(\"{}\", get_or_insert(&mut cache, 7));\n}", "fix_out": "$ rustc --edition 2024 13_map_get_insert_fix.rs && ./13_map_get_insert_fix\nvalue 7\nvalue 7\n", "extras": [{"label": "The same file accepted by the next-generation checker (nightly, -Zpolonius=next)", "out": "$ rustc +nightly --edition 2024 -Zpolonius=next 13_map_get_insert_err.rs && ./13_map_get_insert_err\nvalue 7\n"}]}, {"id": "14_self_borrow", "group": "Borrows", "title": "Calling a &mut self method inside a loop over a field", "code": "E0502", "kind": "compile", "py": "Python methods can touch any attribute at any time.", "read": "The loop borrows <code>self.items<\/code>; <code>self.mark()<\/code> needs <code>&amp;mut self<\/code>, which includes <code>items<\/code>. The checker reasons about whole <code>self<\/code> across a method call.", "why": "Inside one function the checker tracks fields separately, so updating <code>self.seen<\/code> directly is fine. Other fixes: make the helper take only the fields it needs, or iterate over indexes.", "err_src": "struct Batch {\n    items: Vec<String>,\n    seen: usize,\n}\n\nimpl Batch {\n    fn mark(&mut self) {\n        self.seen += 1;\n    }\n    fn process(&mut self) {\n        for item in &self.items {\n            self.mark();\n            println!(\"{item}\");\n        }\n    }\n}\n\nfn main() {\n    let mut b = Batch { items: vec![\"x\".into()], seen: 0 };\n    b.process();\n    println!(\"{}\", b.seen);\n}", "err_out": "$ rustc --edition 2024 14_self_borrow_err.rs\nerror[E0502]: cannot borrow `*self` as mutable because it is also borrowed as immutable\n  --> 14_self_borrow_err.rs:12:13\n   |\n11 |           for item in &self.items {\n   |           -           -----------\n   |           |           |\n   |           |           immutable borrow occurs here\n   |  _________|           immutable borrow later used here\n   | |\n12 | |             self.mark();\n   | |             ^^^^^^^^^^^ mutable borrow occurs here\n13 | |             println!(\"{item}\");\n14 | |         }\n   | |_________- this for loop borrows `*self` immutably, preventing mutation within its body\n   |\n   = help: consider using an index-based loop instead, or collecting modifications into a separate collection\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0502`.\n[exit code 1]\n", "fix_src": "struct Batch {\n    items: Vec<String>,\n    seen: usize,\n}\n\nimpl Batch {\n    fn process(&mut self) {\n        for item in &self.items {\n            self.seen += 1; // touch the field directly: borrows of different fields do not conflict\n            println!(\"{item}\");\n        }\n    }\n}\n\nfn main() {\n    let mut b = Batch { items: vec![\"x\".into(), \"y\".into()], seen: 0 };\n    b.process();\n    println!(\"{}\", b.seen);\n}", "fix_out": "$ rustc --edition 2024 14_self_borrow_fix.rs && ./14_self_borrow_fix\nx\ny\n2\n"}, {"id": "06_return_local_ref", "group": "Lifetimes", "title": "Return a reference to a local", "code": "E0515", "kind": "compile", "py": "Python returns the object itself; reference counting keeps it alive.", "read": "One label: <i>returns a reference to data owned by the current function<\/i>. <code>s<\/code> is freed when the function returns, so a reference to it would dangle.", "why": "Return the owned <code>String<\/code>: ownership moves to the caller, no copy of the bytes is made (the 24-byte header is moved). This is the most common fix for lifetime errors: own instead of borrow.", "err_src": "fn greeting(name: &str) -> &String {\n    let s = format!(\"hello {name}\");\n    &s\n}\n\nfn main() {\n    println!(\"{}\", greeting(\"ada\"));\n}", "err_out": "$ rustc --edition 2024 06_return_local_ref_err.rs\nerror[E0515]: cannot return reference to local variable `s`\n --> 06_return_local_ref_err.rs:3:5\n  |\n3 |     &s\n  |     ^^ returns a reference to data owned by the current function\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0515`.\n[exit code 1]\n", "fix_src": "fn greeting(name: &str) -> String {\n    format!(\"hello {name}\") // return the owned value; the caller owns it now\n}\n\nfn main() {\n    println!(\"{}\", greeting(\"ada\"));\n}", "fix_out": "$ rustc --edition 2024 06_return_local_ref_fix.rs && ./06_return_local_ref_fix\nhello ada\n"}, {"id": "07_missing_lifetime", "group": "Lifetimes", "title": "Which input does the result borrow from?", "code": "E0106", "kind": "compile", "py": "Python has no notion of this; every result is an independent reference.", "read": "<i>the signature does not say whether it is borrowed from <code>a<\/code> or <code>b<\/code><\/i>. With two reference inputs the elision rules cannot pick one, so you must say.", "why": "<code>&lt;'a&gt;<\/code> ties the result to both inputs: callers may use it only while both are alive. It changes no machine code; it is a promise the checker verifies at every call site.", "err_src": "fn pick(a: &str, b: &str, first: bool) -> &str {\n    if first { a } else { b }\n}\n\nfn main() {\n    println!(\"{}\", pick(\"x\", \"y\", true));\n}", "err_out": "$ rustc --edition 2024 07_missing_lifetime_err.rs\nerror[E0106]: missing lifetime specifier\n --> 07_missing_lifetime_err.rs:1:43\n  |\n1 | fn pick(a: &str, b: &str, first: bool) -> &str {\n  |            ----     ----                  ^ expected named lifetime parameter\n  |\n  = help: this function's return type contains a borrowed value, but the signature does not say whether it is borrowed from `a` or `b`\nhelp: consider introducing a named lifetime parameter\n  |\n1 | fn pick<'a>(a: &'a str, b: &'a str, first: bool) -> &'a str {\n  |        ++++     ++          ++                       ++\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0106`.\n[exit code 1]\n", "fix_src": "fn pick<'a>(a: &'a str, b: &'a str, first: bool) -> &'a str {\n    if first { a } else { b }\n}\n\nfn main() {\n    println!(\"{}\", pick(\"x\", \"y\", true));\n}", "fix_out": "$ rustc --edition 2024 07_missing_lifetime_fix.rs && ./07_missing_lifetime_fix\nx\n"}, {"id": "08_outlives", "group": "Lifetimes", "title": "The value dies before its reference", "code": "E0597", "kind": "compile", "py": "Python would keep the string alive because <code>r<\/code> still refers to it.", "read": "<i>borrowed value does not live long enough<\/i>, then <i>dropped here while still borrowed<\/i> at the closing brace, then <i>borrow later used here<\/i>.", "why": "Move the owner to a scope at least as long as the reference's. Rust never extends a value's life to fit a reference; you arrange the scopes, or you own the value.", "err_src": "fn main() {\n    let r;\n    {\n        let model = String::from(\"tiny-llm\");\n        r = &model;\n    }\n    println!(\"{r}\");\n}", "err_out": "$ rustc --edition 2024 08_outlives_err.rs\nerror[E0597]: `model` does not live long enough\n --> 08_outlives_err.rs:5:13\n  |\n4 |         let model = String::from(\"tiny-llm\");\n  |             ----- binding `model` declared here\n5 |         r = &model;\n  |             ^^^^^^ borrowed value does not live long enough\n6 |     }\n  |     - `model` dropped here while still borrowed\n7 |     println!(\"{r}\");\n  |                - borrow later used here\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0597`.\n[exit code 1]\n", "fix_src": "fn main() {\n    let r;\n    let model = String::from(\"tiny-llm\"); // declared in the outer scope: lives as long as r\n    {\n        r = &model;\n    }\n    println!(\"{r}\");\n}", "fix_out": "$ rustc --edition 2024 08_outlives_fix.rs && ./08_outlives_fix\ntiny-llm\n"}, {"id": "09_struct_ref", "group": "Lifetimes", "title": "A struct holding a reference", "code": "E0106", "kind": "compile", "py": "A Python object can hold any reference with no annotation.", "read": "<i>expected named lifetime parameter<\/i> on the field. A struct with a reference inside must say which value it borrows from, so the checker can stop the struct outliving it.", "why": "Either add <code>&lt;'a&gt;<\/code> (zero-copy, but the lifetime then spreads to every type that holds a <code>Chunk<\/code>) or store an owned <code>String<\/code> (one allocation, no lifetime). Owning is usually the right first choice.", "err_src": "struct Chunk {\n    text: &str,\n    start: usize,\n}\n\nfn main() {\n    let doc = String::from(\"a long document\");\n    let c = Chunk { text: &doc[0..6], start: 0 };\n    println!(\"{} at {}\", c.text, c.start);\n}", "err_out": "$ rustc --edition 2024 09_struct_ref_err.rs\nerror[E0106]: missing lifetime specifier\n --> 09_struct_ref_err.rs:2:11\n  |\n2 |     text: &str,\n  |           ^ expected named lifetime parameter\n  |\nhelp: consider introducing a named lifetime parameter\n  |\n1 ~ struct Chunk<'a> {\n2 ~     text: &'a str,\n  |\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0106`.\n[exit code 1]\n", "fix_src": "struct Chunk<'a> {\n    text: &'a str, // a Chunk may not outlive the document it points into\n    start: usize,\n}\n\nstruct OwnedChunk {\n    text: String, // often simpler: own the text, no lifetime needed\n    start: usize,\n}\n\nfn main() {\n    let doc = String::from(\"a long document\");\n    let c = Chunk { text: &doc[0..6], start: 0 };\n    let o = OwnedChunk { text: doc[7..].to_string(), start: 7 };\n    println!(\"{} at {}; {} at {}\", c.text, c.start, o.text, o.start);\n}", "fix_out": "$ rustc --edition 2024 09_struct_ref_fix.rs && ./09_struct_ref_fix\na long at 0; document at 7\n"}, {"id": "12_thread_borrow", "group": "Threads", "title": "A thread borrowing a local", "code": "E0373", "kind": "compile", "py": "A Python thread may read any variable; the object lives as long as someone refers to it.", "read": "<i>closure may outlive the current function<\/i>: <code>thread::spawn<\/code> requires <code>'static<\/code> (the note says so), because the new thread may still run after <code>main<\/code>'s locals are gone.", "why": "<code>move<\/code> gives the thread ownership of <code>docs<\/code>. Or use <code>thread::scope<\/code>: its threads are joined before the scope ends, so they may borrow.", "err_src": "use std::thread;\n\nfn main() {\n    let docs = vec![\"a b\", \"c d e\"];\n    let h = thread::spawn(|| docs.len());\n    println!(\"{}\", h.join().unwrap());\n}", "err_out": "$ rustc --edition 2024 12_thread_borrow_err.rs\nerror[E0373]: closure may outlive the current function, but it borrows `docs`, which is owned by the current function\n --> 12_thread_borrow_err.rs:5:27\n  |\n5 |     let h = thread::spawn(|| docs.len());\n  |                           ^^ ---- `docs` is borrowed here\n  |                           |\n  |                           may outlive borrowed value `docs`\n  |\nnote: function requires argument type to outlive `'static`\n --> 12_thread_borrow_err.rs:5:13\n  |\n5 |     let h = thread::spawn(|| docs.len());\n  |             ^^^^^^^^^^^^^^^^^^^^^^^^^^^^\nhelp: to force the closure to take ownership of `docs` (and any other referenced variables), use the `move` keyword\n  |\n5 |     let h = thread::spawn(move || docs.len());\n  |                           ++++\n\nerror: aborting due to 1 previous error\n\nFor more information about this error, try `rustc --explain E0373`.\n[exit code 1]\n", "fix_src": "use std::thread;\n\nfn main() {\n    let docs = vec![\"a b\", \"c d e\"];\n    let h = thread::spawn(move || docs.len()); // the thread owns docs now\n    println!(\"{}\", h.join().unwrap());\n    let docs2 = vec![\"f\"];\n    let n = thread::scope(|s| s.spawn(|| docs2.len()).join().unwrap()); // or a scoped thread may borrow\n    println!(\"{n} {docs2:?}\");\n}", "fix_out": "$ rustc --edition 2024 12_thread_borrow_fix.rs && ./12_thread_borrow_fix\n2\n1 [\"f\"]\n"}, {"id": "15_rc_refcell_panic", "group": "Run time", "title": "RefCell: the same rule, checked at run time", "code": "panic", "kind": "panic", "py": "Python would append while iterating.", "read": "No compiler error: <code>RefCell<\/code> moves the borrow rules to run time, and breaking them panics with <i>RefCell already borrowed<\/i> at the <code>borrow_mut<\/code> call.", "why": "End the shared borrow before taking the mutable one (compute <code>greet<\/code> first). Use <code>RefCell<\/code> only when the compiler cannot see the pattern; a panic is the price of the run-time check.", "err_src": "use std::cell::RefCell;\n\nfn main() {\n    let history = RefCell::new(vec![String::from(\"hi\")]);\n    for msg in history.borrow().iter() {\n        if msg == \"hi\" {\n            history.borrow_mut().push(String::from(\"hello\")); // compiles; fails at run time\n        }\n    }\n    println!(\"{:?}\", history.borrow());\n}", "err_out": "$ rustc --edition 2024 15_rc_refcell_panic_err.rs && ./15_rc_refcell_panic_err\n\nthread 'main' (16603389) panicked at 15_rc_refcell_panic_err.rs:7:21:\nRefCell already borrowed\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n[exit code 101]\n", "fix_src": "use std::cell::RefCell;\n\nfn main() {\n    let history = RefCell::new(vec![String::from(\"hi\")]);\n    let greet = history.borrow().iter().any(|m| m == \"hi\"); // the shared borrow ends here\n    if greet {\n        history.borrow_mut().push(String::from(\"hello\"));\n    }\n    println!(\"{:?}\", history.borrow());\n}", "fix_out": "$ rustc --edition 2024 15_rc_refcell_panic_fix.rs && ./15_rc_refcell_panic_fix\n[\"hi\", \"hello\"]\n"}]};
